// Generated by tools/make_vectors.py board: the label (1 = square) of each entry of the board's
// image ROM (rtl/image_loader.sv). Bit n of LABELS is entry n, i.e. test image n, and entry 0
// is image 256.
module board_labels (
    input  logic [7:0] entry,
    output logic       label
);

    localparam logic [255:0] LABELS = 256'hc5e3d2c29087f774e46983eb402bc9c05d654d214f5b24c9657d813eb5e40bb6;

    assign label = LABELS[entry];

endmodule
